"""Order total recomputation migrated from Meridian CRM 4.2."""

from decimal import Decimal, ROUND_HALF_UP, localcontext
from typing import Any


_CENT = Decimal("0.01")
_HUNDRED = Decimal("100")


def _decimal(value: Any) -> Decimal:
    """Convert a numeric field using legacy NVL(field, 0) behavior."""
    if value is None:
        return Decimal(0)
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return Decimal(0)
        return Decimal(value)
    if isinstance(value, Decimal):
        return value
    return Decimal(str(value))


def _required_precision(values: list[Decimal]) -> int:
    """Choose sufficient precision for exact intermediate arithmetic."""
    size = 0
    for value in values:
        parts = value.as_tuple()
        size += len(parts.digits) + abs(parts.exponent) + 1
    return max(50, size + 20)


def recompute(
    order: dict, lines: list[dict]
) -> tuple[dict, list[dict], list]:
    """Recompute one order and its supplied lines without mutating inputs."""
    new_order = dict(order)
    new_lines = [dict(line) for line in lines]

    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    live_values: list[tuple[int, Decimal, Decimal]] = []
    context_values: list[Decimal] = []

    for index, line in enumerate(lines):
        if line.get("DEL_FLG") != "Y":
            quantity = _decimal(line.get("QTY", 0))
            unit_price = _decimal(line.get("UNIT_PRC", 0))
            live_values.append((index, quantity, unit_price))
            context_values.extend((quantity, unit_price))

    discount = _decimal(order.get("DISC_PCT", 0))
    incoming_total = _decimal(order.get("TOT_AMT", 0))
    context_values.extend((discount, incoming_total))

    with localcontext() as context:
        context.prec = _required_precision(context_values)

        total = Decimal(0)
        for index, quantity, unit_price in live_values:
            extended = (quantity * unit_price).quantize(
                _CENT, rounding=ROUND_HALF_UP
            )
            new_lines[index]["EXT_AMT"] = float(extended)
            total += extended

        discounted = (
            total * (_HUNDRED - discount) / _HUNDRED
        ).quantize(_CENT, rounding=ROUND_HALF_UP)

    new_order["TOT_AMT"] = float(discounted)

    audits = []
    if incoming_total != discounted:
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))

    return new_order, new_lines, audits
